//! Profile (PGP identity) and location creation, compatible with RetroShare.
//!
//! This mirrors what libretroshare does in
//! `RsLoginHelper::createLocationV2()` / `RsAccountsDetail::GenerateSSLCertificate()`
//! / `AuthSSLimpl::SignX509ReqWithGPG()` / `RNPPGPHandler::GeneratePGPCertificate()`:
//!
//! 1. PGP key: one RSA-4096 primary key (sign + certify + encrypt + auth, no subkeys),
//!    user id `"<name> (Generated by RetroShare) <>"`, protected with the user's password,
//!    stored in `<base>/rnp/retroshare_secret_keyring.gpg` (or `pgp/` for old installs).
//! 2. SSL key: RSA-4096, saved as PKCS#8 PEM encrypted (3DES) with a random
//!    64 character alphanumeric "SSL passphrase" -> `keys/user_pk.pem`.
//! 3. SSL certificate: X509 v1, serial 0x70001, issuer `CN=<PGP ID>`, subject `CN=-`,
//!    valid 2010..2110, signature algorithm sha256WithRSAEncryption, but the signature
//!    itself is an OpenPGP signature (binary document, SHA256) over the DER encoded
//!    TBSCertificate -> `keys/user_cert.pem`.
//! 4. Location id (SSL id) = first 16 bytes of SHA256(signature).
//! 5. The SSL passphrase is PGP encrypted (armored, AES256, ZIP) to the PGP key
//!    -> `keys/ssl_passphrase.pgp`.
//! 6. Location name -> `keys/location_name.txt`; folder renamed to `LOC06_<ssl id>`.

use std::{
    fs::{self, OpenOptions},
    io::{self, Write},
    path::{Path, PathBuf},
};

use openpgp::{
    cert::{prelude::*, CipherSuite},
    crypto::Password,
    packet::signature::SignatureBuilder,
    policy::StandardPolicy,
    serialize::{
        stream::{Armorer, Compressor, Encryptor2, LiteralWriter, Message},
        SerializeInto,
    },
    types::{CompressionAlgorithm, HashAlgorithm, KeyFlags, SignatureType, SymmetricAlgorithm},
};
use openssl::{
    asn1::Asn1Time,
    bn::BigNum,
    hash::MessageDigest,
    pkey::PKey,
    rsa::Rsa,
    symm::Cipher,
    x509::{X509Builder, X509NameBuilder, X509},
};
use colored::Colorize;
use sequoia_openpgp as openpgp;

use ::retroshare_compat::keyring::Keyring;

const KEYRING_SECRET: &str = "retroshare_secret_keyring.gpg";
const KEYRING_PUBLIC: &str = "retroshare_public_keyring.gpg";
/// libretroshare: `SSLPWD_LEN`
const SSL_PASSWORD_LEN: usize = 64;
/// libretroshare: `RS_CERTIFICATE_VERSION_NUMBER_07_0001`
const CERTIFICATE_SERIAL_NUMBER: u32 = 0x0007_0001;
const RSA_BITS: u32 = 4096;

type Res<T> = Result<T, Box<dyn std::error::Error>>;

// ---------------------------------------------------------------------------
// interactive (terminal) front end
// ---------------------------------------------------------------------------

fn prompt(text: &str) -> String {
    print!("{}", text.cyan());
    io::stdout().flush().ok();
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf.trim().to_owned()
}

fn prompt_new_password(text: &str) -> Option<String> {
    loop {
        let pw = rpassword::prompt_password_stdout(&text.cyan().to_string()).ok()?;
        if pw.len() < 4 {
            println!("{}", "password must be at least 4 characters".red());
            continue;
        }
        let pw2 =
            rpassword::prompt_password_stdout(&"Repeat password: ".cyan().to_string()).ok()?;
        if pw != pw2 {
            println!("{}", "passwords do not match, try again".red());
            continue;
        }
        return Some(pw);
    }
}

/// Asks the user for everything needed and creates a new location (and, if wanted,
/// a new profile). Returns the new location folder name on success.
pub fn create_interactive(base_dir: &Path, keys: &Keyring) -> Option<String> {
    println!();
    println!("{}", "=== Create new location ===".green().bold());

    // existing profile or new one?
    let profiles = keys.get_priv_keys();
    let mut existing = None;
    if !profiles.is_empty() {
        println!("{}", "Use an existing profile or create a new one:".cyan());
        for (i, cert) in profiles.iter().enumerate() {
            let name = cert
                .userids()
                .next()
                .map(|u| u.userid().to_string())
                .unwrap_or_default();
            println!(
                " [{}]: {} ({})",
                (i + 1).to_string().yellow(),
                name,
                cert.keyid().to_hex().dimmed()
            );
        }
        println!(" [{}]: new profile", "n".yellow());
        let answer = prompt("> ");
        if !answer.eq_ignore_ascii_case("n") {
            let idx: usize = answer.parse().ok()?;
            existing = Some(profiles.get(idx.checked_sub(1)?)?.clone());
        }
    }

    let (name, password) = match &existing {
        Some(_) => {
            let pw =
                rpassword::prompt_password_stdout(&"Profile password: ".cyan().to_string()).ok()?;
            (String::new(), pw)
        }
        None => {
            let name = loop {
                let n = prompt("Profile name: ");
                if !n.is_empty() {
                    break n;
                }
            };
            let pw = prompt_new_password("Password: ")?;
            (name, pw)
        }
    };

    let mut location = prompt("Location name [My computer]: ");
    if location.is_empty() {
        location = "My computer".into();
    }

    println!("{}", "generating keys, this can take a minute ...".yellow());
    let result = match existing {
        Some(cert) => create_location(base_dir, &cert, &location, &password),
        None => create_profile(base_dir, &name, &password)
            .and_then(|cert| create_location(base_dir, &cert, &location, &password)),
    };

    match result {
        Ok(dir) => {
            println!("{} {}", "created location".green().bold(), dir.green());
            Some(dir)
        }
        Err(err) => {
            println!("{} {}", "failed to create location:".red().bold(), err.to_string().red());
            None
        }
    }
}

// ---------------------------------------------------------------------------
// profile (PGP key)
// ---------------------------------------------------------------------------

/// Folder that holds the keyrings: an existing `rnp` or `pgp` folder, otherwise a new `rnp`.
fn keyring_dir(base_dir: &Path) -> PathBuf {
    for d in ["rnp", "pgp"] {
        let p = base_dir.join(d);
        if p.is_dir() {
            return p;
        }
    }
    base_dir.join("rnp")
}

/// Appends `data` to `file`, keeping a backup of the old file.
fn append_with_backup(file: &Path, data: &[u8]) -> io::Result<()> {
    if file.exists() {
        let backup = file.with_extension("gpg.bak");
        fs::copy(file, &backup)?;
    }
    let mut f = OpenOptions::new().create(true).append(true).open(file)?;
    f.write_all(data)?;
    f.sync_all()
}

/// Creates a new RetroShare compatible PGP profile and stores it in the keyring.
pub fn create_profile(base_dir: &Path, name: &str, password: &str) -> Res<Cert> {
    if password.len() < 4 {
        return Err("password must be at least 4 characters".into());
    }

    let (cert, _revocation) = CertBuilder::new()
        .add_userid(format!("{name} (Generated by RetroShare) <>"))
        .set_cipher_suite(CipherSuite::RSA4k)
        .set_primary_key_flags(
            KeyFlags::empty()
                .set_certification()
                .set_signing()
                .set_transport_encryption()
                .set_storage_encryption()
                .set_authentication(),
        )
        .set_validity_period(None::<std::time::Duration>)
        .set_password(Some(Password::from(password)))
        .generate()?;

    let dir = keyring_dir(base_dir);
    fs::create_dir_all(&dir)?;

    // secret keyring (also contains the public parts)
    append_with_backup(&dir.join(KEYRING_SECRET), &cert.as_tsk().to_vec()?)?;
    // public keyring, only if the installation uses one
    let pub_ring = dir.join(KEYRING_PUBLIC);
    if pub_ring.exists() {
        append_with_backup(&pub_ring, &cert.to_vec()?)?;
    }

    println!(
        "{} '{}' with PGP id {} in {}",
        "created profile".green(),
        name.green().bold(),
        cert.keyid().to_hex().green(),
        dir.display()
    );
    Ok(cert)
}

// ---------------------------------------------------------------------------
// location (SSL key + certificate)
// ---------------------------------------------------------------------------

fn random_ssl_password() -> Res<String> {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut out = String::with_capacity(SSL_PASSWORD_LEN);
    let mut buf = [0u8; 128];
    while out.len() < SSL_PASSWORD_LEN {
        openssl::rand::rand_bytes(&mut buf)?;
        for b in buf {
            // rejection sampling to avoid modulo bias (62 * 4 = 248)
            if (b as usize) < CHARS.len() * 4 && out.len() < SSL_PASSWORD_LEN {
                out.push(CHARS[b as usize % CHARS.len()] as char);
            }
        }
    }
    Ok(out)
}

/// Reads one DER TLV header at `pos`, returns (header length, content length).
fn der_header(data: &[u8], pos: usize) -> Res<(usize, usize)> {
    let first = *data.get(pos + 1).ok_or("DER: truncated")?;
    if first & 0x80 == 0 {
        return Ok((2, first as usize));
    }
    let n = (first & 0x7f) as usize;
    let bytes = data.get(pos + 2..pos + 2 + n).ok_or("DER: truncated")?;
    let len = bytes.iter().fold(0usize, |acc, b| (acc << 8) | *b as usize);
    Ok((2 + n, len))
}

fn der_encode(tag: u8, content: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    let len = content.len();
    if len < 0x80 {
        out.push(len as u8);
    } else {
        let bytes: Vec<u8> = len
            .to_be_bytes()
            .iter()
            .copied()
            .skip_while(|b| *b == 0)
            .collect();
        out.push(0x80 | bytes.len() as u8);
        out.extend(bytes);
    }
    out.extend_from_slice(content);
    out
}

/// Splits a DER encoded X509 certificate into (TBSCertificate, signatureAlgorithm), both
/// including their own TLV headers.
fn split_cert(der: &[u8]) -> Res<(Vec<u8>, Vec<u8>)> {
    let (outer_hl, _) = der_header(der, 0)?;
    let tbs_start = outer_hl;
    let (hl, len) = der_header(der, tbs_start)?;
    let alg_start = tbs_start + hl + len;
    let (hl2, len2) = der_header(der, alg_start)?;
    let alg_end = alg_start + hl2 + len2;
    Ok((
        der[tbs_start..alg_start].to_vec(),
        der.get(alg_start..alg_end).ok_or("DER: truncated")?.to_vec(),
    ))
}

/// Creates a new location for the given profile. `password` is the profile (PGP) password.
/// Returns the folder name, e.g. `LOC06_0123...`.
pub fn create_location(
    base_dir: &Path,
    pgp: &Cert,
    location_name: &str,
    password: &str,
) -> Res<String> {
    let policy = StandardPolicy::new();
    let pgp_id = pgp.keyid().to_hex(); // upper case hex, like RetroShare

    // unlock the PGP key (fails on a wrong password)
    let mut signer = pgp
        .primary_key()
        .key()
        .clone()
        .parts_into_secret()?
        .decrypt_secret(&Password::from(password))
        .map_err(|_| "wrong profile password")?
        .into_keypair()?;

    // --- SSL key ---
    let ssl_password = random_ssl_password()?;
    let ssl_key = PKey::from_rsa(Rsa::generate(RSA_BITS)?)?;
    let ssl_key_pem =
        ssl_key.private_key_to_pem_pkcs8_passphrase(Cipher::des_ede3_cbc(), ssl_password.as_bytes())?;

    // --- X509 certificate (signed with the SSL key first, signature is replaced below) ---
    let mut issuer = X509NameBuilder::new()?;
    issuer.append_entry_by_text("CN", &pgp_id)?;
    let issuer = issuer.build();
    let mut subject = X509NameBuilder::new()?;
    subject.append_entry_by_text("CN", "-")?;
    let subject = subject.build();

    let mut builder = X509Builder::new()?;
    builder.set_version(0)?; // v1
    let serial = BigNum::from_u32(CERTIFICATE_SERIAL_NUMBER)?.to_asn1_integer()?;
    builder.set_serial_number(&serial)?;
    builder.set_issuer_name(&issuer)?;
    builder.set_subject_name(&subject)?;
    let not_before = Asn1Time::from_str("20100101000000Z")?;
    let not_after = Asn1Time::from_str("21100101000000Z")?;
    builder.set_not_before(&not_before)?;
    builder.set_not_after(&not_after)?;
    builder.set_pubkey(&ssl_key)?;
    // sets the signature algorithm fields to sha256WithRSAEncryption
    builder.sign(&ssl_key, MessageDigest::sha256())?;
    let tmp_der = builder.build().to_der()?;

    // --- replace the signature with a PGP signature over the TBSCertificate ---
    let (tbs, alg) = split_cert(&tmp_der)?;
    let pgp_sig = SignatureBuilder::new(SignatureType::Binary)
        .set_hash_algo(HashAlgorithm::SHA256)
        .sign_message(&mut signer, &tbs)?;
    let pgp_sig = openpgp::Packet::from(pgp_sig).to_vec()?;

    let mut bit_string = vec![0u8]; // no unused bits
    bit_string.extend_from_slice(&pgp_sig);
    let mut body = tbs;
    body.extend(alg);
    body.extend(der_encode(0x03, &bit_string));
    let cert_der = der_encode(0x30, &body);
    let cert = X509::from_der(&cert_der)?; // sanity check that it parses
    let cert_pem = cert.to_pem()?;

    // --- location id ---
    let ssl_id = hex::encode(&openssl::sha::sha256(&pgp_sig)[..16]);

    // --- encrypt SSL passphrase to the PGP key ---
    let mut ssl_pw_encrypted = Vec::new();
    {
        let recipients = pgp
            .keys()
            .with_policy(&policy, None)
            .supported()
            .alive()
            .revoked(false)
            .for_transport_encryption()
            .for_storage_encryption();
        let message = Message::new(&mut ssl_pw_encrypted);
        let message = Armorer::new(message).build()?;
        let message = Encryptor2::for_recipients(message, recipients)
            .symmetric_algo(SymmetricAlgorithm::AES256)
            .build()?;
        let message = Compressor::new(message)
            .algo(CompressionAlgorithm::Zip)
            .build()?;
        let mut message = LiteralWriter::new(message).build()?;
        message.write_all(ssl_password.as_bytes())?;
        message.finalize()?;
    }

    // --- write everything to a temp folder, then rename (like RetroShare does) ---
    let tmp_dir = base_dir.join("TMPCFG");
    if tmp_dir.exists() {
        fs::remove_dir_all(&tmp_dir)?;
    }
    let keys_dir = tmp_dir.join("keys");
    fs::create_dir_all(&keys_dir)?;
    fs::create_dir_all(tmp_dir.join("config"))?;
    fs::create_dir_all(tmp_dir.join("gxs"))?;

    fs::write(keys_dir.join("user_pk.pem"), &ssl_key_pem)?;
    fs::write(keys_dir.join("user_cert.pem"), &cert_pem)?;
    fs::write(keys_dir.join("ssl_passphrase.pgp"), &ssl_pw_encrypted)?;
    fs::write(keys_dir.join("location_name.txt"), location_name)?;

    let dir_name = format!("LOC06_{ssl_id}");
    let final_dir = base_dir.join(&dir_name);
    if final_dir.exists() {
        return Err(format!("{} already exists", final_dir.display()).into());
    }
    fs::rename(&tmp_dir, &final_dir)?;

    // make it the preferred location if there is none yet
    let default_file = base_dir.join("default_cert_06.txt");
    if !default_file.exists() {
        fs::write(default_file, &ssl_id).ok();
    }

    println!(
        "{} '{}' with id {} for profile {}",
        "created location".green(),
        location_name.green().bold(),
        ssl_id.green(),
        pgp_id
    );
    Ok(dir_name)
}
